#!/bin/bash
HOST="http://127.0.0.1:3000"
PASS=0; FAIL=0
run() {
  local url="$1"; local body="$2"; local name="$3"
  local code=$(curl -s -o /dev/null -w "%{http_code}" -X POST "$HOST$url" -H 'Content-Type: application/json' -d "$body")
  if [ "$code" = "200" ]; then echo "  PASS $name ($code)"; PASS=$((PASS+1));
  else echo "  FAIL $name ($code) :: $body"; FAIL=$((FAIL+1)); fi
}
echo "=== 101 VASC ==="
run "/api/ir_vasc/pad" '{"stage":"claudication","abi":0.7,"imaging_done":true,"revascularization_offered":false}' "pad"
run "/api/ir_vasc/dvt" '{"type":"proximal","bleeding":false,"anticoag":true,"filter":false,"lysis_needed":false}' "dvt"
